 UPDATE TBL_PROJECT_APPLICATION_H SET
		project_application_status_cd = #{newStatusCd} WHERE project_application_sq =
		#{applicationSq}

 UPDATE TBL_PROJECT_APPLICATION_H SET
		selected_interview_dtm = #{interviewTime}, project_application_status_cd = 805 WHERE
		project_application_sq = #{applicationSq}

