 SELECT
		COALESCE(company_sq, -1) AS groupCompanySq, COUNT(*) AS applicantCount FROM
		TBL_PROJECT_APPLICATION_H WHERE project_sq = #{projectSq}  AND project_application_status_cd = #{status} 
		GROUP BY COALESCE(company_sq, -1) ORDER BY MAX(project_application_created_at_dtm) DESC
		LIMIT #{size} OFFSET #{offset}

 SELECT COUNT(*) FROM ( SELECT 1
		FROM TBL_PROJECT_APPLICATION_H WHERE project_sq = #{projectSq}  AND project_application_status_cd = #{status} 
		GROUP BY COALESCE(company_sq, -1) ) AS grouped
